<script>
(function($){var counter=0,user=0,counterName='',userName='';$('.js-open-counter-select').on('click',function(){counter=Number($(this).data('id'));counterName=$(this).find('.copy').text();$('.js-open-counter-select').removeClass('selected');$(this).addClass('selected');$('.cashier-panel-hidden').removeClass('cashier-panel-hidden');$('#confirm-counter-open').prop('disabled',!user)});$('.js-cashier-select').on('click',function(){user=Number($(this).data('id'));userName=$(this).find('.copy').text();$('.js-cashier-select').removeClass('selected');$(this).addClass('selected');$('#counter-open-confirm-user').text(userName);$('#counter-open-confirm-counter').text(counterName);$('#counter-open-confirm').css('display','flex')});$('#counter-open-confirm-no').on('click',function(){$('#counter-open-confirm').hide()});$('#counter-open-confirm-yes').on('click',function(){$('#counter-open-confirm').hide();var b=$('#confirm-counter-open');b.prop('disabled',true).text('Opening...');$('#open-counter-progress').show();$.getJSON('../counter/api/counter_api.php',{action:'open',counter_id:counter,user_id:user,take_status:3}).done(function(r){if(!r||!r.ok)throw new Error((r&&r.message)||'Could not open counter.');$('#open-counter-progress').text('Counter opened successfully.');if(window.Swal)Swal.fire({icon:'success',title:'Counter Opened',text:'Please log in again.',timer:1300,showConfirmButton:false}).then(function(){location.href='../log_out.php'});else setTimeout(function(){location.href='../log_out.php'},1300)}).fail(function(x){var m=x.responseJSON&&x.responseJSON.message?x.responseJSON.message:'Could not open counter.';$('#open-counter-progress').text(m);if(window.Swal)Swal.fire({icon:'error',title:'Counter not opened',text:m});else alert(m);b.prop('disabled',false).text('Open Counter')})})})(jQuery);
</script>
